// 1. Get the chat message from the trigger
const msg = $('When chat message received').item.json.chatInput || "";

// 2. Extract the first number (Day number)
// Example: "day 7", "give me day 12" → extracts 7 or 12
const match = msg.toString().match(/\d+/);
const dayNumber = match ? match[0] : "0";   // Fallback if no number found

// 3. Get the embedding from OpenAI response
const embedding = $input.item.json.data?.[0]?.embedding || [];

// 4. Build the query_text used for hybrid search
const queryText = `Day ${dayNumber} circadian biology light protocol tiny habits behavioral science`;

// 5. Return clean JSON
return [
  {
    json: {
      day_number: dayNumber,
      embedding,
      query_text: queryText
    }
  }
];

